update_product.code:
const response = await client.products.updateProduct(101, {
    invoice_note: 'Ships in 2 business days',
    advanced: {advance_information: {mpn: 'MPN-0001'}},
});
const product = response.map.product;
console.log(product.invoice_note, product.advanced.advance_information.mpn, product.version);

import_product_reviews.code:
const response = await client.products.importProductReviews(101, {
    product: {
        reviews: [{name: 'Sam Lee', email: 'sam@example.com', rating: 5, review: 'Great shirt', status: 'approved'}],
    },
}, 'IMPORT-2026-10-18');
for (const review of response.map.product.reviews) {
    console.log(review.id, review.name, review.rating, review.status);
}

get_product_stock.code:
const response = await client.products.getProductStock(101);
console.log(response.map.available_stock);
for (const location of response.map.locations) {
    console.log(location.warehouse, location.warehouse_name, location.stock, location.is_default);
}

update_product_stock.code:
const response = await client.products.updateProductStock(101, {
    note: 'Restock',
    locations: [
        {warehouse: 1, stock: 10, low_stock_level: 2, is_default: true},
        {warehouse: 4, stock: 30, low_stock_level: 5, is_default: false},
    ],
});
console.log(response.map.available_stock);
for (const location of response.map.locations) {
    console.log(location.warehouse, location.stock, location.is_default);
}
